CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS resources (key TEXT PRIMARY KEY, id TEXT, operation TEXT, started INTEGER);
CREATE TABLE IF NOT EXISTS panels (key TEXT PRIMARY KEY, channel_id TEXT NOT NULL, message_id TEXT);
CREATE TABLE IF NOT EXISTS categories (id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, expires INTEGER NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tickets (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('purchase','support')), state TEXT NOT NULL DEFAULT 'open', channel_id TEXT UNIQUE, message_id TEXT, assignee TEXT, created INTEGER NOT NULL, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS active_tickets ON tickets(user_id,kind,state);
CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT UNIQUE NOT NULL, user_id TEXT NOT NULL, ticket_id INTEGER UNIQUE REFERENCES tickets(id), status TEXT NOT NULL DEFAULT 'pending', created INTEGER NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS giveaways (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL, message_id TEXT NOT NULL, url TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', review_message_id TEXT, created INTEGER NOT NULL, data TEXT NOT NULL, UNIQUE(user_id,message_id));
CREATE TABLE IF NOT EXISTS reviews (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER UNIQUE NOT NULL REFERENCES orders(id), user_id TEXT NOT NULL, message_id TEXT UNIQUE, published INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS history (id INTEGER PRIMARY KEY AUTOINCREMENT, entity TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, created INTEGER NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS spend (order_id INTEGER PRIMARY KEY REFERENCES orders(id), user_id TEXT NOT NULL, amount INTEGER NOT NULL, currency TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS outbox (id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, data TEXT NOT NULL, created INTEGER NOT NULL);
